<script lang="ts">
  import { onMount } from 'svelte';
  import ArrowDown from '@lucide/svelte/icons/arrow-down';
  import ArrowUp from '@lucide/svelte/icons/arrow-up';
  import GripVertical from '@lucide/svelte/icons/grip-vertical';
  import type { FieldDefinition, JsonValue, ModuleDefinition, ModulePermission, SchemaResponse } from '../../api/domain';
  import { createField, createModule, loadModules, loadModuleSchema, loadSchema, loadStorageLayout, saveStorageLayout, updateField, updateModule, updateSchemaOrder, updateSystemField } from '../../api/workspace';
  import { cloneJson } from '../../util/json';
  import { requestConfirmation } from '../../confirmation';
  import { MODULE_ICON_OPTIONS, normaliseModuleIcon } from '../../util/moduleIcons';

  let schema = $state<SchemaResponse | null>(null); let loading = $state(true); let error = $state(''); let notice = $state('');
  let label = $state(''); let key = $state(''); let type = $state<FieldDefinition['field_type']>('text'); let required = $state(false); let unique = $state(false); let searchable = $state(true); let sortable = $state(true); let visible = $state(true); let priority = $state(50); let options = $state('');
  let autoScope = $state('global'); let autoPrefix = $state(''); let autoPadding = $state(0);
  let attachmentStorage = $state(''); let attachmentDescription = $state(''); let attachmentMultiple = $state(true); let attachmentMaxFiles = $state<number | undefined>(undefined);
  let folders = $state<string[]>([]); let storageCandidate = $state(''); let prefix = $state(''); let preview = $state(''); let storageRoot = $state('records'); let frozen = $state(0); let storageRevision = $state(0); let storageConfigured = $state(false);
  let modules = $state<ModuleDefinition[]>([]); let selectedModuleUid = $state('mx-default-records');
  let moduleName = $state(''); let moduleSingular = $state(''); let moduleDescription = $state(''); let moduleIcon = $state('file-text'); let moduleColor = $state('#1d4ed8');
  let modulePosition = $state(0); let moduleActive = $state(true); let moduleNavigationGroup = $state('');
  let modulePermissions = $state<ModulePermission[]>([]);
  let newModuleName = $state(''); let newModuleSingular = $state('');
  const activeFields = $derived(schema?.fields.filter((field) => field.active).sort((a, b) => a.position - b.position) || []);
  const storageFields = $derived(activeFields.filter((field) => field.field_type !== 'attachments'));
  const selectedModule = $derived(modules.find((module) => module.uid === selectedModuleUid) || null);

  onMount(() => void initialise());
  async function initialise() { try { modules = (await loadModules()).modules; selectedModuleUid = modules.find((module) => module.uid === selectedModuleUid)?.uid || modules[0]?.uid || 'mx-default-records'; syncModuleEditor(); await refresh(); } catch (reason) { fail(reason); loading = false; } }
  function syncModuleEditor() { const module = modules.find((item) => item.uid === selectedModuleUid); if (!module) return; moduleName = module.name; moduleSingular = module.singular_name; moduleDescription = module.description; moduleIcon = normaliseModuleIcon(module.icon); moduleColor = module.color; modulePosition = module.position; moduleActive = module.active; moduleNavigationGroup = typeof module.config.navigation_group === 'string' ? module.config.navigation_group : ''; modulePermissions = cloneJson(module.permissions); }
  async function selectModule() { syncModuleEditor(); await refresh(); }
  function generatedFieldKey() { return label.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').replace(/^[0-9]+/, '') || 'field'; }
  async function refresh() { loading = true; error = ''; try { schema = selectedModuleUid === 'mx-default-records' ? await loadSchema(true) : await loadModuleSchema(selectedModuleUid); const layout = await loadStorageLayout(selectedModuleUid); folders = layout.folder_fields.map((field) => field.uid); prefix = layout.file_prefix_field?.uid || ''; preview = layout.preview; storageRoot = layout.root; frozen = layout.frozen_records; storageRevision = layout.revision; storageConfigured = layout.configured; } catch (reason) { fail(reason); } finally { loading = false; } }
  function fail(reason: unknown) { error = reason instanceof Error ? reason.message : 'The operation failed.'; notice = ''; }
  function configFor(fieldType: string, currentOptions = ''): Record<string, JsonValue> { if (fieldType === 'select') return { options: currentOptions.split(',').map((v) => v.trim()).filter(Boolean) }; if (fieldType === 'attachments') { const maximum = Number(attachmentMaxFiles); return { storage_name: attachmentStorage || key || label, description: attachmentDescription, multiple: attachmentMultiple, max_files: attachmentMultiple && Number.isFinite(maximum) && maximum > 0 ? maximum : attachmentMultiple ? null : 1 }; } if (fieldType === 'auto_number') return { scope: autoScope, prefix: autoPrefix, padding: autoPadding }; return {}; }
  function syncType() { if (type === 'auto_number') { required = true; unique = true; sortable = true; } else if (type === 'attachments') { unique = false; searchable = true; sortable = false; } else if (type === 'long_text') sortable = false; else sortable = true; }
  async function add(event: SubmitEvent) { event.preventDefault(); loading = true; try { await createField({ label, key: key.trim().toLowerCase() || generatedFieldKey(), field_type: type, required: type === 'auto_number' ? true : required, unique_value: type === 'auto_number' ? true : type === 'attachments' ? false : unique, searchable, sortable: ['long_text', 'attachments'].includes(type) ? false : sortable, table_visible: visible, table_priority: priority, config: configFor(type, options) }, selectedModuleUid); label = ''; key = ''; type = 'text'; options = ''; autoScope = 'global'; autoPrefix = ''; autoPadding = 0; attachmentStorage = ''; attachmentDescription = ''; attachmentMultiple = true; attachmentMaxFiles = undefined; required = false; unique = false; searchable = true; sortable = true; notice = 'Field created.'; await refresh(); } catch (reason) { fail(reason); } finally { loading = false; } }
  async function addModule(event: SubmitEvent) { event.preventDefault(); loading = true; try { const result = await createModule({ name: newModuleName, singular_name: newModuleSingular || undefined }); modules = [...modules, result.module].sort((a,b) => a.position-b.position); selectedModuleUid = result.module.uid; newModuleName = ''; newModuleSingular = ''; syncModuleEditor(); notice = 'Module created. Add its fields below.'; await refresh(); } catch (reason) { fail(reason); } finally { loading = false; } }
  async function saveModule() { if (!selectedModule) return; loading = true; try { const result = await updateModule(selectedModule.uid, { name: moduleName, singular_name: moduleSingular, description: moduleDescription, icon: moduleIcon, color: moduleColor, position: modulePosition, active: moduleActive, config: { ...selectedModule.config, navigation_group: moduleNavigationGroup.trim() }, permissions: modulePermissions }); modules = modules.map((module) => module.uid === result.module.uid ? result.module : module).sort((a,b) => a.position-b.position); syncModuleEditor(); notice = 'Module identity, navigation, and access matrix saved.'; } catch (reason) { fail(reason); } finally { loading = false; } }
  async function save(field: FieldDefinition) { try { await updateField(field.uid, { label: field.label, required: field.field_type === 'auto_number' ? true : field.required, unique_value: field.field_type === 'auto_number' ? true : field.field_type === 'attachments' ? false : field.unique_value, searchable: field.searchable, sortable: ['long_text', 'attachments'].includes(field.field_type) ? false : field.sortable, table_visible: field.table_visible, table_priority: field.table_priority, config: field.config }); notice = `${field.label} saved.`; await refresh(); } catch (reason) { fail(reason); } }
  async function toggle(field: FieldDefinition) { const action = field.active ? 'Archive' : 'Restore'; if (!await requestConfirmation({ title: `${action} ${field.label}?`, description: 'Historical values will be preserved.', confirmLabel: `${action} field`, tone: field.active ? 'danger' : 'primary' })) return; try { await updateField(field.uid, { active: !field.active }); await refresh(); } catch (reason) { fail(reason); } }
  function schemaOrderFor(fieldUids: string[]) { if (!schema) return []; if (selectedModuleUid !== 'mx-default-records') return fieldUids.map((id) => ({ kind: 'field', id })); let fieldIndex = 0; return [...schema.system_fields.map((item) => ({ kind: 'system', id: item.key, position: item.position })), ...schema.fields.filter((item) => item.active).map((item) => ({ kind: 'field', id: item.uid, position: item.position }))].sort((a, b) => a.position - b.position).map((item) => item.kind === 'system' ? { kind: item.kind, id: item.id } : { kind: 'field', id: fieldUids[fieldIndex++] || item.id }); }
  async function saveOrder(fieldUids: string[]) { try { await updateSchemaOrder(schemaOrderFor(fieldUids), selectedModuleUid); await refresh(); notice = 'Field order saved.'; } catch (reason) { fail(reason); } }
  async function move(field: FieldDefinition, delta: number) { const ordered = [...activeFields]; const index = ordered.findIndex((item) => item.uid === field.uid); const target = index + delta; if (index < 0 || target < 0 || target >= ordered.length) return; [ordered[index], ordered[target]] = [ordered[target], ordered[index]]; await saveOrder(ordered.map((item) => item.uid)); }
  let draggedField = $state(''); let dragTargetField = $state('');
  function endFieldDrag() { draggedField = ''; dragTargetField = ''; }
  async function dropField(targetUid: string) { if (!draggedField || draggedField === targetUid) { endFieldDrag(); return; } const ordered = [...activeFields]; const from = ordered.findIndex((item) => item.uid === draggedField); const to = ordered.findIndex((item) => item.uid === targetUid); if (from < 0 || to < 0) { endFieldDrag(); return; } const [moved] = ordered.splice(from, 1); ordered.splice(to, 0, moved); endFieldDrag(); await saveOrder(ordered.map((item) => item.uid)); }
  async function saveSystem(keyName: string, visibleValue: boolean, priorityValue: number) { try { await updateSystemField(keyName, { table_visible: visibleValue, table_priority: priorityValue }); await refresh(); } catch (reason) { fail(reason); } }
  function fieldLabel(uid: string) { return activeFields.find((field) => field.uid === uid)?.label || 'Unavailable field'; }
  function addFolder() { if (!storageCandidate || folders.includes(storageCandidate)) return; folders = [...folders, storageCandidate]; storageCandidate = ''; }
  function moveFolder(index: number, delta: number) { const target = index + delta; if (target < 0 || target >= folders.length) return; const next = [...folders]; [next[index], next[target]] = [next[target], next[index]]; folders = next; }
  function removeFolder(index: number) { folders = folders.filter((_, item) => item !== index); }
  function stagedStoragePreview() { const parts = [storageRoot, ...folders.map((uid) => `<${fieldLabel(uid)}>`), '<File Attachment field>']; const prefixField = activeFields.find((field) => field.uid === prefix); parts.push(prefixField ? `<${prefixField.label}>__filename.ext` : 'filename.ext'); return parts.join('/'); }
  async function saveLayout() { try { const result = await saveStorageLayout(folders, prefix || null, selectedModuleUid); preview = result.preview; storageRoot = result.root; frozen = result.frozen_records; storageRevision = result.revision; storageConfigured = result.configured; notice = `Independent N1 layout saved for ${result.module_name}.`; } catch (reason) { fail(reason); } }
</script>

{#if notice}<div class="notice success">{notice}</div>{/if}{#if error}<div class="notice error">{error}</div>{/if}
<section class="panel module-builder"><div class="panel-heading"><div><h2>Modules</h2><p class="muted">Each module has its own identity, fields, records, table preferences, navigation placement, and access matrix.</p></div><label>Editing module<select bind:value={selectedModuleUid} onchange={selectModule}>{#each modules as module}<option value={module.uid}>{module.name}{module.active ? '' : ' (archived)'}</option>{/each}</select></label></div>{#if selectedModule}<div class="module-editor"><label>Name<input bind:value={moduleName} /></label><label>Singular name<input bind:value={moduleSingular} /></label><label>Navigation icon<select bind:value={moduleIcon}>{#each MODULE_ICON_OPTIONS as option}<option value={option.value}>{option.label}</option>{/each}</select></label><label>Color<input bind:value={moduleColor} type="color" /></label><label>Navigation group<input bind:value={moduleNavigationGroup} maxlength="80" placeholder="e.g. Human Resources" /></label><label>Navigation order<input bind:value={modulePosition} type="number" /></label><label class="module-description">Description<input bind:value={moduleDescription} /></label><label class="checkbox"><input type="checkbox" bind:checked={moduleActive} disabled={selectedModuleUid === 'mx-default-records'} /> Module is active</label><button class="button primary" onclick={saveModule} disabled={loading}>Save module</button></div><div class="module-permissions"><div class="permission-head"><strong>Access level</strong><span>View</span><span>Create</span><span>Edit</span><span>Delete</span><span>Configure</span></div>{#each modulePermissions as permission}<div><strong>{['Administrator','Manager','Editor','Viewer'][permission.access_level] || `Level ${permission.access_level}`}</strong><label><input type="checkbox" bind:checked={permission.can_read} disabled={permission.access_level === 0} /><span>View</span></label><label><input type="checkbox" bind:checked={permission.can_create} disabled={permission.access_level === 0} /><span>Create</span></label><label><input type="checkbox" bind:checked={permission.can_update} disabled={permission.access_level === 0} /><span>Edit</span></label><label><input type="checkbox" bind:checked={permission.can_delete} disabled={permission.access_level === 0} /><span>Delete</span></label><label><input type="checkbox" bind:checked={permission.can_configure} disabled={permission.access_level === 0} /><span>Configure</span></label></div>{/each}</div>{/if}<form class="module-create" onsubmit={addModule}><strong>Add another module</strong><input bind:value={newModuleName} required placeholder="Module name, e.g. Cases" /><input bind:value={newModuleSingular} placeholder="Singular, e.g. Case" /><button class="button" disabled={loading}>Create module</button></form></section>
<div class="admin-grid">
  <section class="panel"><h2>Add {selectedModule?.singular_name.toLowerCase() || 'record'} field</h2><form class="form-stack" onsubmit={add}><label>Label<input bind:value={label} required /></label><label>Key (optional override)<input bind:value={key} pattern="[a-z_][a-z0-9_]*" placeholder={`Generated: ${generatedFieldKey()}`} /></label><label>Type<select bind:value={type} onchange={syncType}><option value="text">Text</option><option value="long_text">Long text</option><option value="integer">Integer</option><option value="decimal">Decimal</option><option value="date">Date</option><option value="boolean">Boolean</option><option value="select">Select</option><option value="auto_number">Auto number</option><option value="attachments">File attachments</option></select></label>{#if type === 'select'}<label>Options (comma separated)<input bind:value={options} required /></label>{:else if type === 'auto_number'}<label>Sequence scope<select bind:value={autoScope}><option value="global">Global</option><option value="yearly">Reset yearly</option></select></label><label>Prefix<input bind:value={autoPrefix} /></label><label>Zero padding<input type="number" min="0" max="12" bind:value={autoPadding} /></label>{:else if type === 'attachments'}<label>Storage name<input bind:value={attachmentStorage} placeholder="Defaults to field label" /></label><label>Description<input bind:value={attachmentDescription} /></label><label class="checkbox"><input type="checkbox" bind:checked={attachmentMultiple} /> Allow multiple files</label><label>Maximum files<input type="number" min="1" max="10000" bind:value={attachmentMaxFiles} disabled={!attachmentMultiple} placeholder="Unlimited" /></label>{/if}<label>Table priority<input type="number" bind:value={priority} /></label><label class="checkbox"><input type="checkbox" bind:checked={required} disabled={type === 'auto_number'} /> Required</label><label class="checkbox"><input type="checkbox" bind:checked={unique} disabled={['attachments', 'auto_number'].includes(type)} /> Unique</label><label class="checkbox"><input type="checkbox" bind:checked={searchable} /> Searchable</label><label class="checkbox"><input type="checkbox" bind:checked={sortable} disabled={['long_text', 'attachments'].includes(type)} /> Sortable</label><label class="checkbox"><input type="checkbox" bind:checked={visible} /> Default table column</label><button class="button primary" disabled={loading}>Add field</button></form></section>
  <section class="panel admin-span"><div class="panel-heading"><div><h2>Record structure</h2><p class="muted">Fields drive the record table, editor, reports, and N1 storage.</p></div><span class="security-pill">Revision {schema?.revision || 0}</span></div>
    <div class="schema-list">{#if selectedModuleUid === 'mx-default-records' && schema?.system_fields.length}<h3>Legacy system fields</h3>{#each schema.system_fields as field}<article class="schema-row"><div><strong>{field.label}</strong><small>{field.key} · {field.field_type}</small></div><label class="checkbox"><input type="checkbox" bind:checked={field.table_visible} /> Table</label><label>Priority<input class="short-input" type="number" bind:value={field.table_priority} /></label><button class="button small" onclick={() => saveSystem(field.key, field.table_visible, field.table_priority)}>Save</button></article>{/each}{/if}
      <div class="schema-section-heading"><h3>Custom fields</h3><small>Drag the grip to reorder active fields.</small></div>{#each schema?.fields || [] as field}<article class:dragging={draggedField === field.uid} class:drop-target={dragTargetField === field.uid && draggedField !== field.uid} ondragover={(event) => { if (field.active && draggedField) { event.preventDefault(); dragTargetField = field.uid; } }} ondragleave={(event) => { if (!event.currentTarget.contains(event.relatedTarget as Node | null) && dragTargetField === field.uid) dragTargetField = ''; }} ondrop={(event) => { event.preventDefault(); void dropField(field.uid); }} class:archived={!field.active} class="schema-card"><div class="schema-card-head"><div class="schema-field-title">{#if field.active}<button class="drag-handle" type="button" draggable="true" aria-label={`Drag ${field.label} to reorder`} title="Drag to reorder" ondragstart={(event) => { draggedField = field.uid; event.dataTransfer?.setData('text/plain', field.uid); }} ondragend={endFieldDrag}><GripVertical size={16} /></button>{/if}<div><strong>{field.label}</strong><small>{field.key} · {field.field_type}{field.active ? '' : ' · archived'}</small></div></div><div class="inline-actions"><button class="button small" aria-label="Move up" title="Move up" onclick={() => move(field, -1)} disabled={!field.active || activeFields[0]?.uid === field.uid}><ArrowUp size={15} /></button><button class="button small" aria-label="Move down" title="Move down" onclick={() => move(field, 1)} disabled={!field.active || activeFields[activeFields.length - 1]?.uid === field.uid}><ArrowDown size={15} /></button><button class="button small" onclick={() => toggle(field)}>{field.active ? 'Archive' : 'Restore'}</button></div></div><div class="schema-edit"><label>Label<input bind:value={field.label} /></label><label>Priority<input type="number" bind:value={field.table_priority} /></label><label class="checkbox"><input type="checkbox" bind:checked={field.required} /> Required</label><label class="checkbox"><input type="checkbox" bind:checked={field.unique_value} disabled={['attachments', 'auto_number'].includes(field.field_type)} /> Unique</label><label class="checkbox"><input type="checkbox" bind:checked={field.searchable} /> Searchable</label><label class="checkbox"><input type="checkbox" bind:checked={field.sortable} disabled={['attachments', 'long_text'].includes(field.field_type)} /> Sortable</label><label class="checkbox"><input type="checkbox" bind:checked={field.table_visible} /> Default table column</label>{#if field.field_type === 'select'}<label class="full">Options<input value={(field.config.options as JsonValue[] || []).join(', ')} oninput={(event) => field.config = { options: event.currentTarget.value.split(',').map((v) => v.trim()).filter(Boolean) }} /></label>{:else if field.field_type === 'auto_number'}<label>Scope<select value={String(field.config.scope || 'global')} onchange={(event) => field.config = { ...field.config, scope: event.currentTarget.value }}><option value="global">Global</option><option value="yearly">Reset yearly</option></select></label><label>Prefix<input value={String(field.config.prefix || '')} oninput={(event) => field.config = { ...field.config, prefix: event.currentTarget.value }} /></label><label>Padding<input type="number" min="0" max="12" value={Number(field.config.padding || 0)} oninput={(event) => field.config = { ...field.config, padding: Number(event.currentTarget.value) }} /></label>{:else if field.field_type === 'attachments'}<label>Storage name<input value={String(field.config.storage_name || '')} oninput={(event) => field.config = { ...field.config, storage_name: event.currentTarget.value }} /></label><label>Description<input value={String(field.config.description || '')} oninput={(event) => field.config = { ...field.config, description: event.currentTarget.value }} /></label><label class="checkbox"><input type="checkbox" checked={field.config.multiple !== false} onchange={(event) => field.config = { ...field.config, multiple: event.currentTarget.checked }} /> Multiple files</label><label>Maximum files<input type="number" min="1" max="10000" value={String(field.config.max_files || '')} placeholder="Unlimited" oninput={(event) => { const raw = event.currentTarget.value; field.config = { ...field.config, max_files: raw ? Number(raw) : null }; }} /></label>{/if}<button class="button primary small" onclick={() => save(field)}>Save field</button></div></article>{/each}</div>
  </section>
  <section class="panel admin-wide storage-layout-panel"><div class="panel-heading"><div><h2>N1 storage layouts</h2><p class="muted">Every module has an independent N1 root and folder configuration. Switching this selector loads only that module's layout.</p></div><span class="security-pill">Revision {storageRevision}</span></div><div class="storage-module-context"><div class="storage-module-identity"><i style={`--module-color:${selectedModule?.color || '#1d4ed8'}`}></i><span><strong>{selectedModule?.name || 'Module'} storage</strong><small>{storageConfigured ? 'Custom layout saved' : 'Using the module default'} · {frozen} frozen record folder{frozen === 1 ? '' : 's'}</small></span></div><label>Configure storage for<select bind:value={selectedModuleUid} onchange={selectModule}>{#each modules as module}<option value={module.uid}>{module.name}{module.active ? '' : ' (archived)'}</option>{/each}</select></label><div class="storage-root"><span>Independent N1 root</span><code>{storageRoot}/</code></div></div><div class="storage-builder"><div><label>Add a folder level<select bind:value={storageCandidate}><option value="">Choose a {selectedModule?.singular_name.toLowerCase() || 'record'} field…</option>{#each storageFields.filter((field) => !folders.includes(field.uid)) as field}<option value={field.uid}>{field.label}</option>{/each}</select></label><button class="button" type="button" onclick={addFolder} disabled={!storageCandidate}>Add level</button></div><ol class="storage-order">{#if !folders.length}<li class="storage-empty">Files for {selectedModule?.name || 'this module'} will be stored directly inside each record folder.</li>{/if}{#each folders as uid, index}<li><span class="storage-index">{index + 1}</span><div><strong>{fieldLabel(uid)}</strong><small>Folder level {index + 1}</small></div><div class="inline-actions"><button class="button small" type="button" aria-label="Move up" title="Move up" onclick={() => moveFolder(index, -1)} disabled={index === 0}><ArrowUp size={15} /></button><button class="button small" type="button" aria-label="Move down" title="Move down" onclick={() => moveFolder(index, 1)} disabled={index === folders.length - 1}><ArrowDown size={15} /></button><button class="button small danger" type="button" onclick={() => removeFolder(index)}>Remove</button></div></li>{/each}</ol></div><div class="storage-options"><label>File-name prefix<select bind:value={prefix}><option value="">Keep the uploaded file name</option>{#each storageFields as field}<option value={field.uid}>Prefix with {field.label}</option>{/each}</select></label><div class="storage-preview"><span>New {selectedModule?.singular_name.toLowerCase() || 'record'} path preview</span><code>{stagedStoragePreview()}</code>{#if preview}<small>Currently saved for {selectedModule?.name || 'this module'}: {preview}</small>{/if}</div></div><div class="button-row"><button class="button primary" onclick={saveLayout}>Save {selectedModule?.name || 'module'} layout</button></div></section>
</div>
